(()=>{const group=document.querySelector('.grade-navigation');if(!group)return;const toggle=group.querySelector('button'),menu=group.querySelector('.grade-nav-links');if(!toggle)return;function setOpen(open){menu.hidden=!open;toggle.setAttribute('aria-expanded',String(open));}group.addEventListener('pointerenter',e=>{if(e.pointerType==='mouse')setOpen(true)});group.addEventListener('pointerleave',e=>{if(e.pointerType==='mouse'&&!menu.contains(document.activeElement))setOpen(false)});toggle.addEventListener('click',()=>setOpen(menu.hidden));toggle.addEventListener('keydown',e=>{if(e.key==='ArrowDown'){e.preventDefault();setOpen(true);menu.querySelector('a').focus()}});group.addEventListener('keydown',e=>{if(e.key==='Escape'){e.preventDefault();setOpen(false);toggle.focus()}});group.addEventListener('focusout',()=>setTimeout(()=>{if(!group.contains(document.activeElement))setOpen(false)},0));document.addEventListener('click',e=>{if(!group.contains(e.target))setOpen(false)});menu.addEventListener('click',e=>{if(e.target.closest('a')){setOpen(false);toggle.focus()}});window.addEventListener('hashchange',()=>setOpen(false));})();
