const rooms={screen:{title:'หนึ่งจอ เรียนได้ทั้งห้อง',subtitle:'เด็กไม่ต้องมีโทรศัพท์ส่วนตัว',steps:['ครูเปิดบทเรียนหรือสไลด์บนจอส่วนกลาง','แจกบัตร ก ข ค หรือใบงาน ให้เด็กคิดก่อนยกคำตอบ','ชวนเด็กอธิบายเหตุผล แล้วให้เพื่อนเสนอวิธีอื่น']},computers:{title:'จับคู่เรียน สลับกันลอง',subtitle:'ใช้เครื่องโรงเรียนให้ทุกคนมีส่วนร่วม',steps:['จับคู่เปิดบทเรียนและอ่านเป้าหมายร่วมกัน','สลับคนใช้เมาส์กับคนอธิบาย เมื่อจบแต่ละกิจกรรม','ครูสังเกตวิธีคิด และให้แต่ละคนตอบคำถามสั้น ๆ ด้วยตนเอง']},paper:{title:'กระดาษก็เป็นห้องทดลองได้',subtitle:'ใช้ได้แม้ไม่มีเครื่องหรือไม่มีไฟฟ้า',steps:['เตรียมใบความรู้ ใบงาน และบัตรชื่อไฟล์ที่พิมพ์ไว้ล่วงหน้า','ครูเล่าสถานการณ์ ให้เด็กจัดบัตรไฟล์ลงหมวดหมู่และอธิบายเหตุผล','เก็บคำตอบรายคน แล้วจัดเวลาฝึกทักษะใช้อุปกรณ์จริงกับเครื่องโรงเรียนภายหลัง']}};
