async function api(url,method='GET',data){if(method!=='GET')throw new Error('จัดการเนื้อหาจากเวอร์ชันเครื่องครู');if(url==='/api/session')return {admin:false,setup:false,canManage:false};if(url==='/api/lessons')return [{"id":"safe-online","title":"นักสืบโลกออนไลน์","grade":"ป.4","category":"ความปลอดภัยดิจิทัล","minutes":40,"published":true,"summary":"หยุดคิดก่อนคลิก รู้ทันข้อความแปลก และดูแลข้อมูลส่วนตัวของเรา","objective":"นักเรียนแยกข้อมูลส่วนตัวได้ และอธิบายวิธีรับมือข้อความน่าสงสัยได้อย่างน้อย 2 วิธี","text":"ด่านที่ 1 · ข้อมูลไหนต้องดูแล?\nชื่อจริง ที่อยู่ เบอร์โทร รหัสผ่าน และตำแหน่งที่อยู่เป็นข้อมูลที่ต้องระวังก่อนแบ่งปัน ไม่ส่งรหัสผ่านหรือรหัส OTP ให้ผู้อื่น หากต้องกรอกข้อมูลให้ปรึกษาผู้ปกครองหรือครูก่อน\n\nด่านที่ 2 · ของฟรีอาจมีคำถามซ่อนอยู่\nข้อความว่า ‘รับเกมฟรี! ส่งรหัสผ่านมาทันที’ เป็นสัญญาณให้หยุด อย่าคลิกลิงก์ อย่าตอบกลับ และบอกผู้ใหญ่ที่ไว้ใจ แม้ชื่อผู้ส่งดูเหมือนเพื่อนก็อาจเป็นบัญชีปลอมได้\n\nด่านที่ 3 · นักสืบใช้สูตร หยุด–ตรวจ–บอก\nหยุดก่อนคลิก ตรวจสอบกับแหล่งที่น่าเชื่อถือหรือผู้ใหญ่ และบอกผู้ใหญ่เมื่อพบสิ่งผิดปกติ ถ้าพลาดส่งข้อมูลไปแล้วให้รีบบอก ไม่ต้องกลัวว่าจะถูกตำหนิ\n\nลองคิดด้วยกัน\nคนที่อ้างว่าเป็นเพื่อนในเกมขอที่อยู่เพื่อส่งของขวัญ เราควรทำอย่างไร?","activity":"กิจกรรม 10 นาที: ครูอ่านบัตรสถานการณ์ในใบงาน ให้กลุ่มละ 3–4 คนยกบัตร ‘ทำได้’ หรือ ‘หยุดก่อน’ แล้วบอกเหตุผล สลับคนอ่าน คนคิด และคนอธิบายทุกข้อ ไม่ต้องใช้โทรศัพท์","worksheet":"ชื่อ __________________ ชั้น ______ เลขที่ ______\n\n1. วงกลมข้อมูลที่ไม่ควรโพสต์สาธารณะ: สีที่ชอบ / รหัสผ่าน / ที่อยู่บ้าน / สัตว์ที่ชอบ\n\n2. เขียน ‘ทำได้’ หรือ ‘หยุดก่อน’ พร้อมเหตุผล\nก. บัญชีไม่รู้จักขอรหัสผ่านเพื่อแจกเกม __________________\nเหตุผล _________________________________________\nข. ทำโปสเตอร์เตือนเพื่อนว่าอย่าส่งรหัส OTP ให้คนอื่น __________________\nเหตุผล _________________________________________\nค. เพื่อนจะโพสต์รูปที่ติดป้ายชื่อและที่อยู่ของเรา __________________\nเหตุผล _________________________________________\n\n3. ถ้าเผลอส่งรหัสผ่านไปแล้ว จะขอความช่วยเหลือจากใคร และทำอะไรต่อ?\n________________________________________________\n________________________________________________\n\nบัตรจำง่ายของฉัน: หยุด __________ ตรวจ __________ บอก __________","quiz":[{"question":"มีคนขอรหัสผ่านเพื่อแจกของในเกม ควรทำอย่างไร?","options":["ส่งให้เพื่อรับของ","ไม่ส่ง และบอกผู้ใหญ่ที่ไว้ใจ","ส่งเฉพาะครึ่งแรก"],"correct":1,"explanation":"รหัสผ่านต้องเก็บเป็นความลับ ของรางวัลไม่ใช่เหตุผลให้ส่งรหัสผ่าน"},{"question":"ข้อมูลใดไม่ควรโพสต์สาธารณะ?","options":["สีที่ชอบ","สัตว์ที่ชอบ","ที่อยู่บ้าน"],"correct":2,"explanation":"ที่อยู่บ้านทำให้ผู้อื่นรู้ตำแหน่งของเรา จึงต้องระวังเป็นพิเศษ"},{"question":"เผลอคลิกลิงก์น่าสงสัยแล้ว ควรเริ่มจากอะไร?","options":["บอกผู้ใหญ่ที่ไว้ใจทันที","ปิดบังไว้","ส่งลิงก์ต่อให้เพื่อนลอง"],"correct":0,"explanation":"การขอความช่วยเหลือเร็วช่วยให้ตรวจสอบและแก้ไขได้ทัน"}]},{"id":"files-organizer","title":"ช่วยด้วย! ไฟล์การบ้านหาย","grade":"ป.5","category":"จัดการข้อมูลและไฟล์","minutes":40,"published":true,"summary":"ช่วยต้นตามหาการบ้าน ตั้งชื่อไฟล์ให้รู้เรื่อง และจัดโฟลเดอร์ให้หาเจอง่าย","objective":"นักเรียนตั้งชื่อไฟล์ที่สื่อความหมาย จัดไฟล์ตามหมวดหมู่ และอธิบายขั้นตอนค้นหาไฟล์ได้","text":"การบ้านหาย…หรือแค่หาไม่เจอ?\nต้นทำการบ้านเรื่องวงจรน้ำเสร็จแล้ว แต่หน้าจอมีทั้ง ‘งานใหม่.docx’ และ ‘งานใหม่2.docx’ เราจะช่วยต้นอย่างไรดี?\n\nรู้จักไฟล์และโฟลเดอร์\nไฟล์คืองานหนึ่งชิ้น เช่น เอกสาร รูปภาพ หรือสไลด์ ส่วนโฟลเดอร์ช่วยรวมไฟล์เป็นหมวดหมู่ ลองนึกถึงกระดาษแต่ละแผ่นที่เก็บไว้ในแฟ้ม\n\nชื่อชัด อ่านแล้วรู้เรื่อง\nชื่อ ‘วิทย์_วงจรน้ำ_ต้น.docx’ บอกวิชา เรื่อง และเจ้าของงานได้ชัดกว่า ‘งานใหม่2.docx’ ส่วน .docx คือนามสกุลไฟล์เอกสาร ไม่ควรเปลี่ยนเองเพียงเพื่อให้ชื่อสวยขึ้น\n\nเก็บเป็นหมวด\nนำการบ้านวงจรน้ำไว้ในโฟลเดอร์วิทยาศาสตร์ เรื่องเล่าไว้ในภาษาไทย และรูปวาดไว้ในศิลปะ เราเลือกวิธีจัดหมวดหมู่อื่นได้ ถ้าอธิบายเหตุผลและค้นหาได้สะดวก\n\nหาเจอทีละขั้น\n1. ค้นด้วยคำที่จำได้จากชื่อ เช่น ‘วงจรน้ำ’\n2. ดูชื่อและตำแหน่งว่าอยู่ในโฟลเดอร์ใด\n3. เปิดตรวจว่าเป็นงานที่ต้องการก่อนส่งครู\n\nจำง่าย ๆ: ชื่อชัด • เก็บเป็นหมวด • หาเจอง่าย","activity":"ภารกิจกลุ่ม 15 นาที: ครูแจกบัตรชื่อไฟล์ 3 ใบ ได้แก่ วิทย์_วงจรน้ำ.docx, ไทย_เรื่องเล่า.docx และ ศิลปะ_สวนดอกไม้.png พร้อมป้ายโฟลเดอร์วิทยาศาสตร์ ภาษาไทย และศิลปะ ให้เด็กจับคู่และอธิบายเหตุผล\n\nจากนั้นแต่ละคู่เขียนบัตรไฟล์การบ้านของตนเอง ตั้งชื่อให้สื่อความ แล้วแลกให้เพื่อนเลือกโฟลเดอร์และบอกคำที่ใช้ค้นหา สลับคนตั้งชื่อกับคนค้นหา ใช้กระดาษแทนคอมพิวเตอร์ได้","worksheet":"ชื่อ __________________ ชั้น ______ เลขที่ ______\n\n1. จับคู่ไฟล์กับโฟลเดอร์\nก. วิทย์_วงจรน้ำ.docx → __________________\nข. ไทย_เรื่องเล่า.docx → __________________\nค. ศิลปะ_สวนดอกไม้.png → __________________\nโฟลเดอร์ที่เลือกได้: วิทยาศาสตร์ / ภาษาไทย / ศิลปะ\n\n2. เปลี่ยนชื่อ ‘งานใหม่2.docx’ ให้บอกว่าเป็นการบ้านภาษาไทยเรื่องคำคล้องจองของเรา โดยคง .docx ไว้\nชื่อใหม่ ________________________________________\nเพราะ _________________________________________\n\n3. เรียงขั้นตอนค้นหาไฟล์ โดยใส่หมายเลข 1–3\n___ เปิดตรวจว่าใช่งานที่ต้องการ\n___ ค้นด้วยคำที่จำได้จากชื่อไฟล์\n___ ดูชื่อและตำแหน่งไฟล์\n\n4. ถ้ามีรูปวาดแมว จะตั้งชื่อและเก็บไว้ในโฟลเดอร์อะไร?\nชื่อไฟล์ (คงนามสกุล .png) _________________________\nโฟลเดอร์ _______________________________________\nเหตุผล _________________________________________","quiz":[{"question":"ชื่อไฟล์ใดช่วยให้รู้ว่าเป็นการบ้านเรื่องอะไรและของใคร?","options":["งานใหม่2.docx","วิทย์_วงจรน้ำ_ต้น.docx","ส่งครูด่วน.docx"],"correct":1,"explanation":"ชื่อที่บอกวิชา เรื่อง และเจ้าของงาน ช่วยให้ค้นหาและแยกไฟล์ได้ง่าย"},{"question":"โฟลเดอร์มีประโยชน์อย่างไร?","options":["ช่วยรวมไฟล์เป็นหมวดหมู่","ทำให้ทุกไฟล์กลายเป็นรูปภาพ","ลบการบ้านเก่าให้อัตโนมัติ"],"correct":0,"explanation":"โฟลเดอร์ช่วยจัดเก็บไฟล์ที่เกี่ยวข้องไว้ด้วยกัน เพื่อให้หาได้สะดวก"},{"question":"ค้นเจอไฟล์ชื่อคล้ายการบ้านแล้ว ควรทำอะไรก่อนส่งครู?","options":["ส่งไฟล์แรกทันที","เปลี่ยนนามสกุลไฟล์ให้สวย","ดูตำแหน่งและเปิดตรวจว่าใช่งานที่ต้องการ"],"correct":2,"explanation":"ชื่อที่คล้ายกันอาจเป็นคนละงาน จึงควรตรวจเนื้อหาและตำแหน่งก่อนส่ง"}]},{"id":"check-before-share","title":"เช็กให้ชัวร์ก่อนแชร์","grade":"ป.6","category":"รู้เท่าทันสื่อ","minutes":40,"published":true,"summary":"สวมหมวกนักตรวจข่าว ดูที่มา วันที่ และหลักฐาน ก่อนเชื่อหรือส่งต่อ","objective":"นักเรียนตรวจข้อมูลจากผู้เผยแพร่ วันที่ และหลักฐานได้ พร้อมอธิบายเหตุผลก่อนตัดสินใจแชร์","text":"เห็นบ่อย ไม่ได้แปลว่าจริง\nข้อความที่ถูกส่งต่อหลายครั้งอาจผิดหรือเก่าแล้วก็ได้ ภาพสวยและยอดกดถูกใจไม่ใช่หลักฐานยืนยันความจริง\n\nนักตรวจข่าวมี 3 คำถาม\n1. ใครเป็นผู้เผยแพร่? เป็นหน่วยงานหรือผู้รู้เรื่องนี้จริงหรือไม่ และเราตรวจสอบต้นทางได้ไหม\n2. เผยแพร่เมื่อไร? ข้อมูลเก่าอาจไม่ตรงกับเหตุการณ์ปัจจุบัน\n3. มีหลักฐานอะไร? เปรียบเทียบกับประกาศต้นทางหรือแหล่งที่น่าเชื่อถืออีกแห่ง อย่านับหลายโพสต์ที่คัดลอกข้อความเดียวกันว่าเป็นหลายหลักฐาน\n\nถ้ายังไม่แน่ใจ\nยังไม่ส่งต่อ บอกว่า ‘ยังตรวจสอบไม่ได้’ และขอให้ครูหรือผู้ปกครองช่วยตรวจ การไม่รีบสรุปเป็นทักษะที่ดี\n\nกรณีฝึกทั้งหมดเป็นเรื่องสมมติ\nข้อความ ‘พรุ่งนี้โรงเรียนหยุด ส่งต่อด่วน!’ ที่ไม่บอกชื่อโรงเรียนและวันที่ ยังใช้ยืนยันการหยุดเรียนไม่ได้","activity":"กิจกรรม 15 นาที: แจกบัตรข่าวสมมติจากใบงานให้กลุ่มละ 3 คน คนแรกดูผู้เผยแพร่ คนที่สองดูวันที่ คนที่สามดูหลักฐาน แล้วนำเสนอว่าต้องตรวจอะไรเพิ่ม ครูรับบทเป็นแหล่งข้อมูลต้นทางให้เด็กมาถามได้","worksheet":"ชื่อ __________________ ชั้น ______ เลขที่ ______\n\nบัตรข่าวสมมติ A: ‘พรุ่งนี้หยุดเรียนทุกโรงเรียน ส่งต่อด่วน!’ ผู้ส่งไม่ทราบชื่อ ไม่มีวันที่ ไม่มีประกาศแนบ\nบัตรข่าวสมมติ B: ‘โรงเรียนต้นไม้จัดกิจกรรมอ่านหนังสือ วันที่ 15 สิงหาคม 2570’ ระบุผู้เผยแพร่ว่าเป็นโรงเรียนต้นไม้ และแนบภาพประกาศ แต่ยังไม่ได้ตรวจสอบกับโรงเรียน\n\n1. ข่าว A ขาดข้อมูลอะไรบ้าง?\n________________________________________________\n2. ข่าว B มีข้อมูลมากกว่า แต่ควรตรวจอะไรต่อก่อนเชื่อ?\n________________________________________________\n3. หากวันนี้ไม่ใช่วันที่ในประกาศ จะนำข่าวไปบอกว่าเป็นกิจกรรมวันนี้ได้หรือไม่ เพราะอะไร?\n________________________________________________\n4. เขียนคำตอบสุภาพถึงคนที่ส่งข่าว A โดยไม่ส่งข่าวต่อ\n________________________________________________\n________________________________________________\n5. เติมบัตรนักตรวจข่าว: ใคร __________ เมื่อไร __________ หลักฐาน __________","quiz":[{"question":"ข่าวถูกแชร์มาก แปลว่าจริงเสมอหรือไม่?","options":["จริง เพราะคนส่วนใหญ่เชื่อ","จริง ถ้ามีภาพสวย","ไม่เสมอ ต้องตรวจที่มาและหลักฐาน"],"correct":2,"explanation":"ยอดแชร์บอกความแพร่หลาย แต่ไม่ได้รับรองความถูกต้อง"},{"question":"เห็นข้อความว่า ‘พรุ่งนี้หยุดเรียน’ แต่ไม่มีวันที่ ควรทำอะไร?","options":["หยุดเรียนเลย","ตรวจประกาศจากโรงเรียนหรือถามครู","ส่งให้ทุกคนทันที"],"correct":1,"explanation":"ควรตรวจข้อมูลต้นทางและวันที่ก่อนใช้ตัดสินใจ"},{"question":"ยังตรวจสอบข่าวไม่ได้ ควรเลือกข้อใด?","options":["ยังไม่แชร์ และขอผู้ใหญ่ช่วยตรวจ","เดาว่าน่าจะจริง","เปลี่ยนข้อความให้ดูน่าเชื่อ"],"correct":0,"explanation":"เมื่อข้อมูลไม่พอ เราสามารถรอตรวจสอบก่อนส่งต่อได้"}]}];throw new Error('คำสั่งนี้ใช้ในเวอร์ชันเครื่องครู');}
function toast(s){const t=document.querySelector('#toast');t.textContent=s;t.style.display='block';setTimeout(()=>t.style.display='none',3500);}
async function refresh(){session=await api('/api/session');lessons=await api('/api/lessons');document.querySelector('#adminButton').textContent=session.admin?'ห้องคุณครู':'โหมดคุณครู';document.querySelector('#adminButton').hidden=!session.canManage;document.querySelector('#shareLink').hidden=false;}
function auth(){if(!session.canManage){toast('เปิดโหมดคุณครูจากเครื่องครูเท่านั้น');return;}const d=document.querySelector('#auth');document.querySelector('#authTitle').textContent=session.setup?'ตั้งค่าห้องคุณครูครั้งแรก':'ยินดีต้อนรับคุณครู';document.querySelector('#authHelp').textContent=session.setup?'ตั้งรหัสผ่านอย่างน้อย 8 ตัวอักษรสำหรับจัดการบทเรียนบนเครื่องนี้':'กรอกรหัสผ่านเพื่อเพิ่มและแก้ไขสื่อการสอน';document.querySelector('#authError').textContent='';document.querySelector('#loginForm').reset();d.showModal();}
document.querySelector('#adminButton').onclick=()=>session.admin?location.hash='admin':auth();
document.querySelector('.close').onclick=()=>document.querySelector('#auth').close();
document.querySelector('#loginForm').onsubmit=async e=>{e.preventDefault();const b=e.target.querySelector('[type=submit]');b.disabled=true;try{await api(session.setup?'/api/setup':'/api/login','POST',{password:new FormData(e.target).get('password')});await refresh();document.querySelector('#auth').close();location.hash='admin';route();}catch(e){document.querySelector('#authError').textContent=e.message;}finally{b.disabled=false;}};
